contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount > 0);

        uint256 cBalanceBefore = address(c).balance;

        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 cBalanceAfter = address(c).balance;

        // go must not revert, forwards exactly `amount` out, then drains any
        // remaining balance to owner, so c's post-balance is always zero and
        // the amount leaving c is exactly the prior balance plus the amount sent in.
        assert(
            !reverted &&
            cBalanceAfter == 0 &&
            cBalanceBefore + amount - cBalanceAfter == cBalanceBefore + amount
        );
    }

    receive() external payable {}
}

